css:
*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; font: 16px/1.6 "Liberation Sans", Arial, sans-serif; color: #1d2320; background: #fbfbf8; }
.bar { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-bottom: 1px solid #e0e2dc; background: #fff; }
.bar strong { font-size: 18px; }
.menu-btn { font: inherit; padding: 6px 12px; border: 1px solid #7d857f; border-radius: 6px; background: #fff; }
/* Pattern: off-canvas drawer — hidden off the left edge on narrow screens, a sidebar from 768px. */
.drawer { position: fixed; inset: 0 auto 0 0; width: 18rem; padding: 20px; background: #24302a; color: #f2f5f1; transform: translateX(-100%); transition: transform 0.2s ease; z-index: 10; }
.drawer.open { transform: none; }
.drawer ul { list-style: none; margin: 0; padding: 0; }
.drawer li { padding: 8px 0; }
.drawer a { color: inherit; text-decoration: none; }
main { max-width: 680px; margin: 0 auto; padding: 24px 16px; }
@media (min-width: 768px) {
  .menu-btn { display: none; }
  .page { display: grid; grid-template-columns: 16rem minmax(0, 1fr); }
  .drawer { position: sticky; top: 0; height: 100vh; width: auto; transform: none; transition: none; }
}
